  "test_path": "tests/unit/test_span_filter_extra.py",
  "test": "import importlib
import os
from types import SimpleNamespace

import pytest


def make_span(scope_name: str):
    return SimpleNamespace(instrumentation_scope=SimpleNamespace(name=scope_name), attributes=None)


def test_is_known_llm_instrumentor_extra_prefix(monkeypatch):
    # Set extra prefix via env var
    monkeypatch.setenv("LANGFUSE_EXTRA_LLMS", "custom.llm")
    import langfuse.span_filter as sf
    importlib.reload(sf)
    span = make_span("custom.llm.some_child")
    assert sf.is_known_llm_instrumentor(span) is True

    # Without the env var, the same prefix should not be recognized
    monkeypatch.delenv("LANGFUSE_EXTRA_LLMS", raising=False)
    importlib.reload(sf)
    span2 = make_span("custom.llm.some_child")
    assert sf.is_known_llm_instrumentor(span2) is False
